insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('bb983020-bf14-4cce-ac21-4da3f261bd23','ja','kia-tigers-namhaeng-yeolcha','KIAタイガース『南行列車』応援歌','湖南地方を本拠地とするKIAタイガースを象徴する代表的な応援歌。','パティ・キムの『あなたなしでは生きられない』を原曲とする『南行列車』は、KIAタイガースの本拠地である湖南地方を象徴する応援歌で、通常は試合終盤にKIAが勝利を確実にした場面で流れる。この曲が流れると、応援団長の指示がなくてもファンが自然と立ち上がって一緒に歌うのが恒例となっている。『鯨狩り』『木浦の涙』とともに、KIAの非公式な象徴曲として挙げられる。','KIAタイガース(前身はヘテタイガース)の応援文化の中で定着した。','KIAタイガースのファン文化と湖南地方のアイデンティティを象徴する応援歌として紹介する際に使われる。',NULL,array['南行列車','KIA타이거즈 남행열차 응원가']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('63d40611-cfe4-47ff-92dd-c05ba452b3e1','ja','ahn-jung-hwan-ring-ceremony','アン・ジョンファンの指輪セレモニー','2002年W杯ベスト16イタリア戦でのゴールデンゴール直後に見せた、アン・ジョンファンの指輪キスセレモニー。','2002年日韓W杯ベスト16のイタリア戦で、アン・ジョンファンが延長戦でゴールデンゴールを決めた後、指にはめた指輪に口づけするセレモニーを披露し、『指輪の王様』というニックネームが付いた。このゴールで韓国はベスト8進出を果たしたが、当のアン・ジョンファンは所属クラブから放出される痛手を味わった。','2002年6月18日、韓国対イタリアのベスト16戦でのアン・ジョンファンの決勝ゴールセレモニー。','2002年W杯の名場面を語るときにすぐ通じる表現。',NULL,array['指輪の王様','ゴールデンゴールセレモニー','안정환 반지 세리머니']::text[],'[{"text": "この瞬間、まさにアン・ジョンファンの指輪の王様級の名場面だ", "situation": "カカオトーク"}, {"text": "W杯の名場面といえばこのセレモニーだよね", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('558036e1-500c-427a-a522-6b341199a56a','ja','sweet-venom-challenge','「Sweet Venom」チャレンジ','フェイカーが参加して話題を呼んだENHYPENの『Sweet Venom』ダンスチャレンジ。','2024年1月、リーグ・オブ・レジェンドの選手フェイカーが、サムスンGalaxy S24 Ultraのプロモーションキャンペーンの一環としてENHYPENと『Sweet Venom』ダンスチャレンジに参加し話題となった。楽曲自体は2023年11月にリリースされたが、チャレンジの流行は2024年初めにピークを迎えた。','2024年1月、サムスンとENHYPENの公式コラボチャレンジ(フェイカー参加)。','eスポーツとK-POPのコラボ事例として言及される。',NULL,array['スウィートベノムチャレンジ','ENHYPENスウィートベノム','Sweet Venom 챌린지']::text[],'[{"text": "このチャレンジ、フェイカーとENHYPENのコラボを思い出す", "situation": "カカオトーク"}, {"text": "こういうコラボはSweet Venom級の話題性だ", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('80ec8a9f-99c5-4a1c-bc5a-a5b0142b564c','ja','emergency-committee-ya-andwae','非常対策委員会「ヤ、アンドゥエ」','キム・ウォニョが言い訳をしながら叫ぶ、ゲグコンサートの流行語。','2011~2012年、KBSのお笑い番組『ゲグコンサート』のコーナー『非常対策委員会』で、警察の制服を着たキム・ウォニョが状況を取り繕おうと『ヤ、アン~ドゥエェ!』と叫んだ流行語。学校暴力防止教育など実際の現場でもパロディされるほど影響力が大きかった。','2011年、KBS『ゲグコンサート』の『非常対策委員会』コーナー、キム・ウォニョ。','困った状況を止めようと叫ぶときに使う。',NULL,array['キム・ウォニョ アンドゥエ','ヤ、アン~ドゥエェ','비상대책위원회 ''야 안돼''']::text[],'[{"text": "ヤ、アン~ドゥエェ!ww(困ったときに)", "situation": "カカオトーク"}, {"text": "この叫び方、完全に非常対策委員会st", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('1e274da7-0435-4995-a33e-79a93f89bd06','ja','hyun-jin-young-blurred-memory-of-you','ヒョン・ジニョン『霞んだ記憶の中のあなた』','1990年代初頭、ソ・テジワ・アイドルのライバルとされたヒョン・ジニョンのヒップホップダンス曲。','1990年代初頭、ヒョン・ジニョンはヒップホップダンス曲『霞んだ記憶の中のあなた』で大人気を博し、当時のソ・テジワ・アイドルに対抗できる強力なライバルの一人とされた。イ・スマンがプロデュースした新人として、1992年8月に2集『New Dance 2』のタイトル曲としてこの曲を発表し、KBS歌謡トップ10で5週、MBC『皆さんの人気歌謡』で9週連続、SBS人気歌謡で8週連続1位を記録するなど、当時最高のヒット曲の一つに数えられた。同時期にデビューしたソ・テジワ・アイドルの人気を何度も阻むほどの対抗馬とされ、ヒョン・ジニョンとワワはその強力なライバルグループとして語り継がれた。','ヒョン・ジニョンはイ・スマンがプロデュースした新人で、1992年8月に2集『New Dance 2』のタイトル曲『霞んだ記憶の中のあなた』を発表した。完成度の高いヒップホップダンス曲として大ヒットし、当時最高のヒット曲の一つに数えられた。','1990年代初頭のヒップホップダンス音楽の代表例として挙げられる。',NULL,array['霞んだ記憶の中のあなた','현진영 ''흐린 기억 속의 그대''']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('a17fe5d5-d8e0-412d-b956-c3f1f555282c','ja','jobutsu-kimdo','成仏(キム・ド)','アニメ『あの日見た花の名前を僕達はまだ知らない。』の名台詞のBGMが、PUBGの勝利クリップと組み合わさって生まれたミーム。','アニメ『あの日見た花の名前を僕達はまだ知らない。』でキャラクターのめんまが成仏する場面のBGMを、配信者キム・ドが放送終了曲として使用したことから始まった。その後、キム・ドがPUBGで劇的に1位を達成したクリップに同じBGMを合成した動画が拡散し、困難な目標を成し遂げた瞬間を指して『成仏した』と表現するミームになった。','配信者キム・ドの放送終了曲とPUBGクリップの合成(2017~2019年頃、Twitch Korea)。','難しい目標を劇的に達成したときに使われる表現。',NULL,array['チムチャンメン成仏','성불(김도)']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('99f4a285-ad60-4918-b9a9-8ba2c60a30e8','ja','girls-generation-gee-dog-leg-dance','少女時代『Gee』犬足ダンス','少女時代『Gee』の犬足ダンスが世代を超えて流行し、スキニージーンズブームまで巻き起こした。','2009年1月に発売された少女時代の『Gee』は、振り付けの中で脚を交差させる『犬足ダンス』が、可愛らしくコミカルな魅力で老若男女に愛されて流行した。楽曲の人気とともにカラースキニージーンズが全国民的なファッションアイテムになるほど影響力が大きく、各種音楽チャートでも新記録を打ち立てた。','SMエンターテインメント所属、少女時代『Gee』(2009年1月)の振り付けに由来。','2009年のガールズグループのダンス・ファッション流行を振り返る際に使う。',NULL,array['Gee脚ダンス','犬足ダンス','소녀시대 Gee 개다리춤']::text[],'[{"text": "今でも犬足ダンス踊るとみんな喜ぶよねw", "situation": "カカオトーク"}, {"text": "このスキニージーンズ完全にGee時代st", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('ceac8ebc-86f8-4f6a-8e16-d1e43f319199','ja','lee-kyung-kyu-hidden-camera','イ・ギョンギュの隠しカメラ','1991年に始まったイ・ギョンギュの『隠しカメラ』コーナーから生まれた慣用句。','1991年4月から放送されたMBC『日曜日日曜日の夜に』の『隠しカメラ』コーナーをイ・ギョンギュが進行したことで、『イ・ギョンギュ=隠しカメラ』という図式が大衆に定着した。以後、誰かにいたずらを仕掛けられると『隠しカメラじゃない?』と尋ねる言い回しが長く使われた。','1991年4月、MBC『日曜日日曜日の夜に』のコーナーとして新設され、イ・ギョンギュが進行を担当し1992年11月まで放送された。隠しカメラで有名人や一般人の反応を撮るこのフォーマットが大ヒットし、『隠しカメラ』という言葉自体が韓国の放送用語として定着するきっかけになった。欧米のブルーパー映像文化や日本の『ドッキリ』番組の影響を受けたと推測され、以後韓国のバラエティ番組で隠しカメラフォーマットが一つのジャンルとして定着した。','予想外の隠しカメラ的ないたずらに遭ったときに使える。',NULL,array['隠しカメラ','イ・ギョンギュ=隠しカメラ','이경규 몰래카메라']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('b4b88383-852e-4fd3-8682-44ec680d10ff','ja','abracadabra-cocky-dance','『Abracadabra』小生意気ダンス','無表情で腰だけ振る、ブラウンアイドガールズの代表的な流行りダンス。','2009年夏、ブラウンアイドガールズの『Abracadabra』がヒットし、メンバーのガインが披露した、無表情のまま骨盤だけを左右に振る『小生意気ダンス』が芸能人たちの間で最高のパロディ振り付けとなった。','ブラウンアイドガールズ3集タイトル曲の振り付け中、ガインのパートに由来。','クールな表情でふざけるときのパロディとして使われる。',NULL,array['ガインの小生意気ダンス','ブラウンアイドガールズのAbracadabra','아브라카다브라 시건방춤']::text[],'[{"text": "無表情で腰だけ振るの完全に小生意気ダンスだ", "situation": "カカオトーク"}, {"text": "ガインの小生意気ダンス、今でも伝説", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7be750f6-b507-4a02-a604-a6d5c656e595','ja','kkungttari-shabara','クンタリ・シャバラ','クローンをスターダムに押し上げた、サビの中毒性が強いダンス曲。','1996年に発売されたクローンの1集『Are You Ready?』のタイトル曲で、『꿍따리 샤바라』が正式表記だが、『쿵따리 샤바라』としてより広く呼ばれている。当時新人だったクローンをその年のSBS歌謡大賞などで受賞させた楽曲で、独特なサビと振り付けは今も宴会やレトロコンテンツの定番ネタとなっている。','クローン1集『Are You Ready?』タイトル曲(1996年5月)。','陽気なサビや中毒性の高いフックソングを語るときに引用される。',NULL,array['クンタリシャバラ(異表記)','クローン クンタリシャバラ','꿍따리 샤바라']::text[],'[{"text": "飲み会のカラオケはクンタリシャバラ必須でしょ", "situation": "飲み会のグループチャット"}, {"text": "このサビ、今でも中毒性やばい", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('e91345bf-e355-40d2-b7da-b44dbdfe44dc','ja','spot-challenge','「SPOT!」チャレンジ','ジコがジェニーをフィーチャリングした新曲『SPOT!』に合わせたダンスチャレンジ。','2024年4月26日に発売されたジコの『SPOT!(feat. JENNIE)』が公開されるとすぐ、ジコ本人が投稿したダンスチャレンジ動画をきっかけにSNSで爆発的に拡散した。発売から3日で関連動画が約2万件投稿され、中国の抖音(Douyin)では振り付けチャレンジのハッシュタグの同時視聴者数が1000万人を超えるなど、アジア全域で流行した。','ジコが新曲発売直後にSNSへ投稿したダンスチャレンジ動画。','K-POPダンスチャレンジの事例として言及される。',NULL,array['ジコ・ジェニーチャレンジ','SPOT! 챌린지']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('c386286e-8aec-491d-bf1c-f7b7f660b0c2','ja','lee-jong-beom-son-of-the-wind','李鍾範『風の息子』','俊足の盗塁で塁上を沸かせた李鍾範に付いた国民的なニックネーム。','歌手のハ・チョンイルが、野球用品店の常連客だった李鍾範に『盗塁するとき風を巻き起こして入る』という意味でこのニックネームを贈った。李鍾範は1994年に1シーズン84盗塁を記録するなど、圧倒的な走塁能力を見せつけた。その後、息子の李政厚がデビューし『風の孫』というニックネームを受け継ぎ、親子二代のニックネームの系譜が続いている。','1990年代初頭、ハ・チョンイルが名付けたニックネームがメディアとファンの間で定着した。','李鍾範の代表的なニックネームで、息子・李政厚の『風の孫』とともに言及される。',NULL,array['風の息子','이종범 바람의 아들']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('3bf49ea4-75c8-425a-b924-e75e8726ada8','ja','kang-ho-dong-youngest-cheonhajangsa','カン・ホドン 最年少天下壮士','22歳でシルム(韓国相撲)の最年少天下壮士に輝いた後、芸能人に転身したカン・ホドンの物語。','カン・ホドンは1990年3月、第24回天下壮士シルム大会決勝でパク・グァンドクを3対2で下し、通算5度目の天下壮士のタイトルを獲得した。天下壮士5回、白頭壮士7回という驚異的な記録を残したが、最年少天下壮士という肩書きの重圧に耐えられなかったとして、1992年、22歳でシルムを引退した。その後、イ・ギョンギュの勧めでお笑い芸人に転身し、放送人として第二の全盛期を迎えた。','1990年のカン・ホドンの天下壮士就位と1992年の早期引退。','シルム選手出身の放送人カン・ホドンの原点となるキャリアを紹介する際に使われる。',NULL,array['강호동 최연소 천하장사']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('de40c608-caf3-4060-b8de-3163536fbd17','ja','how-much-would-it-take','いくらあればいいの、いくらあればいいんだよ','2000年のドラマ『秋の童話』でウォンビンが残した名台詞。','KBSドラマ『秋の童話』でウォンビンが演じたキャラクターが放った台詞で、愛をお金で測ろうとする態度を象徴する言葉となり、以後20年以上にわたって様々なパロディや引用に使われている。','2000年、KBSドラマ『秋の童話』放送中に登場した台詞。','俗物的な態度を風刺する際に引用する。','なし',array['いくらあればいいの','얼마면 돼, 얼마면 되는데']::text[],'[{"text": "そんなにお金お金言うなら完全にいくらあればいいのウォンビンstだね", "situation": "カカオトーク"}, {"text": "あの台詞見るといくらあればいいのって思い出すw", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('cc41e01d-27b0-436d-9301-65d909128363','ja','cho-sung-mo-asinayo','チョ・ソンモ『アシナヨ(知っていますか)』','ベトナム戦争を背景にした映画級のミュージックビデオで話題を集めた2000年のヒット曲。','2000年9月に発売されたチョ・ソンモ3集のタイトル曲で、ベトナム戦争を舞台にした大作ミュージックビデオにチョン・ジュノ、シン・ミナ、ホ・ジュノらスター俳優が出演し話題となった。このアルバムはその年最も売れたアルバムとなり、H.O.T、ソ・テジ、godを抑えて年末授賞式の大賞を受賞した。','2000年9月1日、チョ・ソンモの正規3集タイトル曲として発売。','ドラマ仕立てのミュージックビデオの全盛期を語るときに言及される。',NULL,array['チョ・ソンモ3集タイトル曲','조성모 - 아시나요']::text[],'[{"text": "このMV完全にチョ・ソンモのアシナヨ級の映画クオリティだ", "situation": "カカオトーク"}, {"text": "その年最も売れたアルバムだったよね", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('37c8756a-7d73-4624-9a59-76431d5b61a5','ja','this-najin-wins','これをナジンが勝つのか','録画中継の結果流出から生まれた劇的逆転ネタ。','2012年、IPL韓国代表選抜戦のナジン・ソード対ナジン・シールドの試合が録画中継で放送された際、視聴者が戦績検索サイトで先に結果を調べたことから生まれた。シールドが実際の試合展開では不利な状況が続いていたにもかかわらず、結果的に勝利することを知っていた視聴者が『これをナジンが勝つのか』というネタを書き込み流行した。以後、劇的な逆転勝利を表す言葉として定着した。','2012年、IPL韓国代表選抜戦ナジン・ソード対ナジン・シールドの録画中継。','不利に見えていた側が劇的に勝利したときに使う。',NULL,array['これをナジンが','이걸 나진이 이기네']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d3b06433-383f-432e-badd-f24bb3ea8257','ja','coopers-worry-about-yourself','クーパーズ『あなたこそ心配しなさい』','別主簿伝(うさぎと亀の物語)をモチーフに、シングがうさぎの代わりに人々にぴしゃりと言い放ったホッケ飲料広告のコピー。','2005年、韓国ヤクルトのホッケナムクーパーズ(ホッケの木クーパーズ)の広告は、朝鮮の伝統説話『別主簿伝』をモチーフに、肝臓の健康のために東海を訪れたシングが『あなたこそ心配しなさい』と言い放つ内容で話題を集めた。原作の説話をパロディ化してユーモラスに製品メッセージを伝えた事例として挙げられる。無愛想だが親しみやすいシングのキャラクターがよく活かされた広告と評価されている。','2005年、韓国ヤクルト ホッケナムクーパーズのテレビCM、シング出演。','おせっかいを言ってくる相手に切り返す言葉として『あなたこそ心配しなさい』を引用する。',NULL,array['シング クーパーズ','쿠퍼스 너나 걱정하세요']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d758a9ab-867a-4c14-a026-d9b9f6b180f1','ja','jul-eul-seosio-line-up','並びなさい','ドラマ『ホジュン』でイム・ヒョンシクが残したアドリブの名台詞。','1999年に放送が始まったMBCの時代劇『ホジュン』で、イム・オグン役のイム・ヒョンシクが押し寄せる患者たちを整理しながら叫んだアドリブの台詞。最高視聴率60%台を記録した国民的ドラマの名場面として、今でもパロディに使われる。','MBCドラマ『ホジュン』(1999~2000年)、イム・ヒョンシク演じるイム・オグン役。','順番や待機を急かす状況を時代劇風にパロディする際に引用する。',NULL,array['ホジュン イム・ヒョンシク','줄을 서시오']::text[],'[{"text": "並びなさい~ww(時代劇口調で)", "situation": "カカオトーク"}, {"text": "このアドリブ今でも伝説", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('eed137bb-f38c-453c-9454-bfec76aa5a6d','ja','pumpkin-sweet-potato','カボチャさつまいも','発音がもつれて一文字ずつ大声で叫ぶ場面が名場面として残ったミーム。','2006年11月14日放送のシットコム『遠慮なくハイキック』第7話で、ナ・ムニが『カボチャさつまいも(호박고구마)』という単語をうまく発音できず、一文字ずつ区切って大声で叫ぶ場面から生まれた。イ・スンジェが『このばあさんは何をやってるんだ、食卓で!』と反応する場面とともに、ハイキックシリーズの名場面投票で1位を獲得するほど長く語り継がれている場面である。','MBCシットコム『遠慮なくハイキック』第7話(2006年11月14日)、ナ・ムニ演じる役。','発音がもつれたり、ぎこちない状況を面白おかしく表現するときに使う。',NULL,array['カボチャさつまいも(一文字ずつ)','カボチャさつまいも事件','호박고구마']::text[],'[{"text": "さっき発表中に言葉がもつれて完全にカボチャさつまいもになったよw", "situation": "カカオトーク"}, {"text": "あの発音、完全にカボチャさつまいも級の名場面", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9683b236-260c-4537-8969-3b9c3e50d5d5','ja','final-four-myth','4強神話','2002年W杯で韓国が4強入りを果たしたことを指す表現。','開催国・韓国がベスト4まで勝ち上がった2002年W杯の成果を指す象徴的な表現で、その後も予想を超える奇跡的な成果を比喩する際に広く使われている。ヒディンク監督率いる代表チームの挑戦と、国民総出の街頭応援が生み出した結果という意味も込められている。','2002年日韓W杯で大韓民国代表チームがベスト4入りした成果をメディアが命名。','予想外の大きな成果を比喩する際に使う。',NULL,array['大韓民国4強神話','4강 신화']::text[],'[{"text": "今回のプロジェクト、完全に4強神話級の成果じゃない?", "situation": "会社のチャット"}, {"text": "これくらいなら4強神話の再現だね", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
